from __future__ import annotations
from itertools import combinations
from typing import FrozenSet, List, Set

Topology = FrozenSet[FrozenSet[int]]  # a topology = family of open sets on a finite carrier


def join(topologies: List[Topology], carrier: FrozenSet[int]) -> Topology:
    """Consensus (join): the topology generated by sets open in EVERY observer.

    On a finite carrier the consensus open sets are exactly the intersection of
    the observers' open-set families (already a topology, since each family is a
    topology and the intersection of topologies is a topology).
    """
    common = set(topologies[0])
    for t in topologies[1:]:
        common &= set(t)
    return frozenset(common)


def phantom_number(target: Topology, candidates: List[Topology],
                   carrier: FrozenSet[int], max_k: int = 4) -> int:
    """Least k such that some k strictly-finer candidates have join == target."""
    finer = [c for c in candidates if set(target) <= set(c) and set(c) != set(target)]
    for k in range(1, max_k + 1):
        for combo in combinations(finer, k):
            if join(list(combo), carrier) == target:
                return k
    return -1
